import{z as o,x as i,o as B,c as d,q as r,j as l,D as E,d as t,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"队列动力学的建模","description":"","frontmatter":{"title":"队列动力学的建模","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-queue-dynamics.md","filePath":"quant/obd-queue-dynamics.md","lastUpdated":1791063341000}'),u={name:"quant/obd-queue-dynamics.md"};function m(p,a,D,h,q,C){const A=i("Mermaid");return B(),d("div",null,[a[2]||(a[2]=r('<h1 id="队列动力学的建模" tabindex="-1">队列动力学的建模 <a class="header-anchor" href="#队列动力学的建模" aria-label="Permalink to &quot;队列动力学的建模&quot;">​</a></h1><div class="epigraph"><p>队列不是存放存货的仓库，是被三支速率推着走的状态：限价挂进来、撤销抽出去、市价吃下去——每支速率看着队列的长度，再决定下一步。</p><footer>—— 据 Huang, Lehalle and Rosenbaum, JASA, 2015；Bouchaud 等, Trades, Quotes and Prices, 2018 整理</footer></div><p><a href="/quant/research-postmortem">上一课</a>把研究的闭环收在证据链上：失败与成功同模板归档，死因必须落在判据上，\\(N\\) 的完整性靠台账维持。量化主干至此走完一圈；本课是「订单簿动力学深化」的第一课，主干已交付三块基石：<a href="/quant/lob-structure">限价订单簿</a>的状态机、<a href="/quant/queue-reactive">queue-reactive</a> 的状态依赖强度、<a href="/quant/hawkes-lob">Hawkes 订单簿</a>的时间自激。本课程不重复这些定义，而是把「簿怎么动」本身当对象：先建模队列，再问冲击、订单流与逆向选择，再看截面与时间的稳定形态，最后落到方法。第一课钉住建模目标：一个队列模型要对上哪些可观测量才算合格。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/lob-structure">限价订单簿</a>给出了队列的静态描述，<a href="/quant/queue-reactive">queue-reactive</a> 给出了第一层动力学：限价、撤销、市价的强度是当前队列长度与价差的函数。缺口在评价标准：估计出 \\(\\lambda^{\\mathrm{LO}}(q)\\)、\\(\\lambda^{\\mathrm{C}}(q)\\)、\\(\\lambda^{\\mathrm{MO}}(q)\\) 之后，什么叫做「对上了数据」？只匹配平均深度是廉价的合格——强度定错的模型也能在均值上凑对，却在存活时间、耗尽补量、深度自相关上全错；下游的成交概率与逆向选择度量吃的正是这些条件统计，不是均值。</p><p><span class="marginnote">术语翻译：强度 \\(\\lambda\\) 就是「下一瞬某类事件发生的速率」——\\(\\lambda^{\\mathrm{C}}=3\\) 表示此刻每秒平均撤 3 笔；把它写成队列长度的函数 \\(\\lambda(q)\\)，意思是「队列剩多少个单位时，撤销速率是多少」，这比一个全程平均数多出来的正是状态。</span></p><h3 id="要对上的统计清单" tabindex="-1">要对上的统计清单 <a class="header-anchor" href="#要对上的统计清单" aria-label="Permalink to &quot;要对上的统计清单&quot;">​</a></h3><p>建模目标固定成一张清单：队列长度的边际分布；队头存活时间与耗尽概率；吃薄后的补量速度；深度与中点波动的自相关；价差状态的停留时间。任何新的队列模型都按同一张清单交卷，并写明放弃了哪几条。</p><p><span class="marginnote">一个便宜的判别：队头存活时间接近指数，说明给定状态后事件已无记忆，QR 式状态依赖大体够用；显著重尾或成簇，说明还有自激没被状态吸收——先加状态、再谈核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态取双侧最优档 \\((q^{b},q^{a})\\) 加价差 \\(s\\)，事件字典沿用 <a href="/quant/hawkes-lob">Hawkes 订单簿</a>的口径：限价、撤销、成交分侧计数，改单拆成撤加增。强度用事件暴露时间估计，不用墙钟采样——稀疏时段会低估强度。价格运动写成耗尽：一侧最优档打到零，中间价跳一档，新档深度从初始化分布里抽。估出来的是按开盘、午间、收盘分段的函数族；日内相位的系统处理留给后课。</p><p>自激加不加由数据裁决：控制住 \\((q^{b},q^{a},s)\\) 之后残差仍成串，再加核。先状态后自激是识别问题：两个通道都有解释力，不分先后就分不清系数，仿真会把余震错误记成状态变化。</p>',12)),(B(),l(n,null,{default:E(()=>[s(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E4%BA%8B%E4%BB%B6%E5%AD%97%E5%85%B8%EF%BC%9A%E9%99%90%E4%BB%B7%2F%E6%92%A4%E9%94%80%2F%E6%88%90%E4%BA%A4%22%5D%20--%3E%20INT%5B%22%E5%BC%BA%E5%BA%A6%20%CE%BB%20%E6%8C%89%E4%BC%9A%E8%AF%9D%E5%88%86%E6%AE%B5%22%5D%0A%20%20INT%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%E7%8A%B6%E6%80%81%E6%9B%B4%E6%96%B0%22%5D%0A%20%20Q%20--%3E%20DEP%7B%22%E4%B8%80%E4%BE%A7%E6%9C%80%E4%BC%98%E6%A1%A3%E8%80%97%E5%B0%BD%EF%BC%9F%22%7D%0A%20%20DEP%20--%3E%7C%E6%98%AF%7C%20MOVE%5B%22%E4%B8%AD%E9%97%B4%E4%BB%B7%E8%B7%B3%E4%B8%80%E6%A1%A3%EF%BC%8C%E6%96%B0%E6%A1%A3%E6%B7%B1%E5%BA%A6%E9%87%8D%E6%8A%BD%22%5D%0A%20%20DEP%20--%3E%7C%E5%90%A6%7C%20Q%0A%20%20MOVE%20--%3E%20STAT%5B%22%E7%BB%9F%E8%AE%A1%E6%B8%85%E5%8D%95%EF%BC%9A%E5%88%86%E5%B8%83%2F%E5%AD%98%E6%B4%BB%2F%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Q%20--%3E%20STAT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"状态依赖的机制是时间优先下的拥挤税：队列越长，新挂单位排得越后、等待期权越不值钱，撤销相对变多；队列被打薄，补量涌进来抢队头。深度被拉向一个统计上的舒适区间——均值回复是这个机制的产物，不是外加的正则项。自激的机制是行为传染：一笔大市单引来模仿单或止损单，事件在时间上成串。两股力同时存在，分配错了，仿真要么把簿抖成噪声，要么把余震记成新状态。",-1)),a[5]||(a[5]=e("p",null,"深度的均值回复是两支速率推出来的平衡，回路本身值得单独看：",-1)),(B(),l(n,null,{default:E(()=>[s(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LONG%5B%22%E9%98%9F%E5%88%97%E5%8F%98%E9%95%BF%22%5D%20--%3E%20CT%5B%22%E6%8B%A5%E6%8C%A4%E7%A8%8E%3A%E6%96%B0%E5%8D%95%E4%BD%8D%E6%8E%92%E4%BD%8D%E9%9D%A0%E5%90%8E%22%5D%0A%20%20CT%20--%3E%20CINC%5B%22%E6%92%A4%E9%94%80%E7%9B%B8%E5%AF%B9%E5%8F%98%E5%A4%9A%22%5D%0A%20%20CINC%20--%3E%20SHORT%5B%22%E9%98%9F%E5%88%97%E5%8F%98%E7%9F%AD%22%5D%0A%20%20SHORT%20--%3E%20REF%5B%22%E8%A1%A5%E9%87%8F%E6%B6%8C%E6%9D%A5%E6%8A%A2%E9%98%9F%E5%A4%B4%22%5D%0A%20%20REF%20--%3E%20LONG%0A%20%20BIG%5B%22%E5%A4%A7%E5%B8%82%E5%8D%95%E6%89%93%E8%BF%9B%3A%E8%A1%8C%E4%B8%BA%E4%BC%A0%E6%9F%93%22%5D%20--%3E%20CLUS%5B%22%E6%A8%A1%E4%BB%BF%E5%8D%95%2F%E6%AD%A2%E6%8D%9F%E5%8D%95%E6%88%90%E7%B0%87%E5%87%BA%E7%8E%B0%22%5D%0A%20%20CLUS%20--%3E%20JUDGE%7B%22%E5%BD%92%E7%BB%99%E7%8A%B6%E6%80%81%E8%BF%98%E6%98%AF%E8%87%AA%E6%BF%80%3F%22%7D%0A%20%20JUDGE%20--%3E%7C%22%E9%94%99%E8%AE%B0%E6%88%90%E7%8A%B6%E6%80%81%22%7C%20E1%5B%22%E4%BD%99%E9%9C%87%E8%A2%AB%E5%BD%93%E6%88%90%E6%96%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20JUDGE%20--%3E%7C%22%E9%94%99%E8%AE%B0%E6%88%90%E8%87%AA%E6%BF%80%22%7C%20E2%5B%22%E7%B0%BF%E8%A2%AB%E6%8A%96%E6%88%90%E5%99%AA%E5%A3%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：把队头想成景点的售票窗口——队太长时，后面的人觉得「轮不到我」陆续离开（撤销升）；队一短，新游客立刻凑上来抢位置（补量升）。深度的「舒适区间」就是这两股人流平衡出来的，不是谁设定的目标值。</span></p><p>这个分配有下游后果：把市价强度直接当自己的填成强度，忽略了「你挂上去之后状态已经变了」；逆向选择也要按队列状态条件化，薄档被吃与厚档被吃的信息含量不同。两个下游话题本课只留接口。</p><p><span class="marginnote">为什么重要：下游成交概率吃的是条件统计——按「队头还剩 3 个位子」算出的成交概率，与按平均深度算的可以差出数倍；均值上合格的模型，在排队与撤单决策上给出的答案可以完全相反。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可见队列只是可成交量的下界：冰山让市价强度的观测带低偏，这是数据层次问题，改陡函数补不上。模型是约化的：它不区分知情与否，把 \\(\\lambda(q)\\) 读成信念超出识别集。开环仿真只对统计诊断有效；把自己的订单放进去，就进入了被干预的世界，要靠仿真校准的纪律兜底。制度时段、涨跌停与竞价衔接都会改写速率系数，跨段混估等于宣布形状不变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>队列动力学的建模对象是速率族对状态的依赖，不是一张平均深度表。</li><li>验收按统计清单交卷：边际分布、存活时间、耗尽与补量、自相关；均值对齐不等于合格。</li><li>价格运动写成耗尽加新档初始化，中点波动可以是内生产物。</li><li>可见队列带隐藏量偏差；开环诊断与闭环干预是两个世界。</li><li>出处：Huang, Lehalle and Rosenbaum, <em>JASA</em>, 2015；Bouchaud 等, <em>Trades, Quotes and Prices</em>, 2018；状态机定义见<a href="/quant/lob-structure">限价订单簿</a>。</li></ul>',7))])}const F=o(u,[["render",m]]);export{b as __pageData,F as default};
